        const describedBy = helpText ? ` aria-describedby="${id}-help"` : "";

        return `
          <div class="form-field" data-question="${id}">
            <fieldset${describedBy}>
              <legend>
                <span class="question-index">Question ${index + 1}</span>
                <span class="question-title">${prompt}</span>
              </legend>
              ${helpText ? `<p class="question-help" id="${id}-help">${helpText}</p>` : ""}
              <div class="choices">
                ${options.map((option) => CheckboxChoice({ questionId: id, option })).join("")}
              </div>
              <p class="question-feedback" id="${id}-feedback"></p>
            </fieldset>
          </div>
        `;
      };

      const QuizApp = () => `
        <div class="page-shell">
          <header class="hero">
            <p class="eyebrow">Interactive quiz</p>
            <main id="maincontent" tabindex="-1">
              <h1>Computer languages knowledge check</h1>
