       const QuizApp = () => `
         <div class="page-shell">
           <header class="hero">
             <p class="eyebrow">Interactive quiz</p>
           </header>

           <main id="maincontent" tabindex="-1">
             <h1>Computer languages knowledge check</h1>
             <p>
               Explore three multi-select questions covering web technologies, compiled languages,
               and data-focused languages.
             </p>

             <section class="quiz-card" aria-labelledby="quiz-heading">
               <div class="quiz-meta">
                 <h2 id="quiz-heading" class="sr-only">Quiz form</h2>
                 <p>Choose every answer you believe is correct for each question, then submit to see your score.</p>
                 <div class="status-message" id="quiz-status" aria-live="polite">
                   Pick your answers and press Submit quiz when you're ready.
                 </div>
               </div>

               <form id="quiz-form">
                 ${quizData.map((question, index) => QuizQuestion(question, index)).join("")}
                 <div class="actions">
                   <button class="submit-button" type="submit">Submit quiz</button>
                 </div>
               </form>
             </section>
           </main>
         </div>
       `;

       const isExactMatch = (selectedValues, correctValues) => {
         if (selectedValues.length !== correctValues.length) {
           return false;
         }

         const selectedSet = new Set(selectedValues);
         return correctValues.every((value) => selectedSet.has(value));
       };

       const renderQuiz = () => {
         const app = document.getElementById("app");
         app.innerHTML = QuizApp();

         const form = document.getElementById("quiz-form");
         const status = document.getElementById("quiz-status");

         form.addEventListener("submit", (event) => {
           event.preventDefault();

           let score = 0;

           quizData.forEach((question) => {
             const selectedValues = Array.from(
               form.querySelectorAll(`input[name="${question.id}"]:checked`)
             ).map((input) => input.value);

             const isCorrect = isExactMatch(selectedValues, question.correctAnswers);
             const field = form.querySelector(`[data-question="${question.id}"]`);
             const feedback = document.getElementById(`${question.id}-feedback`);

             field.dataset.state = isCorrect ? "correct" : "incorrect";

             if (isCorrect) {
               score += 1;
               feedback.textContent = "Correct selection.";
             } else if (selectedValues.length === 0) {
               feedback.textContent = "No answers selected.";
             } else {
               feedback.textContent = "Not quite. Review the selected choices and try again.";
             }
           });

           const allCorrect = score === quizData.length;
           status.dataset.tone = allCorrect ? "success" : "warning";
           status.textContent = allCorrect
             ? `Great work — you scored ${score} out of ${quizData.length}.`
             : `You scored ${score} out of ${quizData.length}. You can update your answers and submit again.`;
         });
       };

       renderQuiz();
     </script>
   </body>
')

